mapper.select:
SELECT COUNT(*)
FROM ${table} d
WHERE d.uploader_user_id = #{userId}

  AND d.meeting_id = #{meetingId}

SELECT d.doc_id, d.uploader_user_id, u.name AS uploader_name, d.meeting_id, d.original_name, d.filepath, d.mime_type, d.size, d.sha256, d.original_lang, d.storage_key, d.uploaded_at, d.use_context_rag FROM ${table} d LEFT JOIN tl_users u ON u.user_id = d.uploader_user_id WHERE d.uploader_user_id = #{userId}
AND d.meeting_id = #{meetingId}
ORDER BY d.uploaded_at DESC, d.doc_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM ${table}
WHERE doc_id = #{docId}
  AND uploader_user_id = #{userId}

mapper.update:
UPDATE ${table}
SET use_context_rag = CASE WHEN use_context_rag = 1 THEN 0 ELSE 1 END
WHERE doc_id = #{docId}
  AND uploader_user_id = #{userId}

mapper.select:
SELECT *
FROM tl_meeting_documents
WHERE meeting_id   = #{meetingId}
  AND doc_type     = 'TRANSLATION'
  AND trans_doc_id = #{transDocId}
LIMIT 1
